import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch38Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm10_en_174","sm11-5_en_057","sm7-5_en_062","swsh10_en_154","swsh2_en_165","xy4_en_091","xy5_en_124","xy5_en_133","xy9-5_en_066");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void play(ServerMatch m){m.playTrainer(A,card(m,A,"trainer").instanceId(),null);}
    static void pick(ServerMatch m,UUID id){var q=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,q.resolutionId(),q.step(),id);}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static GeneratedRuleBatch28Test.Config config(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile(id);if(id.equals("sm7-5_en_062")||id.equals("xy5_en_124"))c.ownTypes=c.evolvedTypes=Set.of(EnergyType.WATER);if(id.equals("xy5_en_133"))c.ownTypes=c.evolvedTypes=Set.of(EnergyType.FIGHTING);return c;}
    static ServerMatch aiGame(String id){var m=GeneratedRuleBatch28Test.fixture(config(id));if(id.equals("xy5_en_124")||id.equals("xy5_en_133")){var keep=card(m,A,"trainer");m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().filter(c->!c.equals(keep)).map(CardInstance::instanceId).toList());}return m;}
    public static void main(String[] args){revival();returns();exile();switchHealing();System.out.println("NonPokemonBatch38Test passed: last-hand typed any-stage revival with actual placement draw, full Pokemon stack return versus attachment discard, V/GX exclusion, undamaged Bench-only disposal, and healing the old Active after switching");}
    static void revival(){for(String id:List.of("xy5_en_124","xy5_en_133")){
        var m=GeneratedRuleBatch28Test.fixture(config(id));check(!m.canPlayTrainer(A,card(m,A,"trainer").instanceId(),null),"Revival ignored last-card restriction");var keep=card(m,A,"trainer");var evolved=card(m,A,"evolved");m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().filter(c->!c.equals(keep)).map(CardInstance::instanceId).toList());int deck=m.privateView(A).deck().size();play(m);var q=m.effectCardPrompt(A);EnergyType type=id.equals("xy5_en_124")?EnergyType.WATER:EnergyType.FIGHTING;check(q.candidates().contains(evolved)&&q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).pokemonTypes().contains(type)),"Revival excluded evolution or included wrong type");m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(evolved.instanceId()));settle(m);check(m.benchPokemonView(A).stream().anyMatch(p->p.topCardId().equals("evolved"))&&m.privateView(A).hand().size()==5&&m.privateView(A).deck().size()==deck-5,"Revival failed any-stage placement/draw");
        var empty=GeneratedRuleBatch28Test.fixture(config(id));var source=card(empty,A,"trainer");empty.shuffleHandIntoDeckByEffect(A,A);empty.searchOwnDeckToHandByEffect(A,List.of(source.instanceId()));check(!empty.canPlayTrainer(A,source.instanceId(),null),"Revival allowed draw with no Pokemon in discard");
    }}
    static void returns(){for(String id:List.of("xy4_en_091","swsh2_en_165")){
        var m=GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.GRASS,EnergyType.GRASS,profile(id),GeneratedRuleBatch8Test.hit(10,false));UUID host=m.benchPokemonView(A).getFirst().pokemonId();var base=m.benchPokemonView(A).getFirst().topCardId();var evolution=card(m,A,"evolved");var energy=card(m,A,"special");var tool=card(m,A,"tool");m.evolve(A,host,evolution.instanceId());m.attachEnergy(A,energy.instanceId(),host);m.attachToolByEffect(A,A,EffectSourceZone.HAND,tool.instanceId(),A,host);int basics=(int)m.privateView(A).hand().stream().filter(c->c.definitionId().equals(base)).count();play(m);pick(m,host);settle(m);check(m.benchPokemonView(A).isEmpty()&&m.privateView(A).hand().contains(evolution)&&m.privateView(A).hand().stream().filter(c->c.definitionId().equals(base)).count()==basics+1&&m.privateView(A).discard().containsAll(List.of(energy,tool))&&!m.privateView(A).hand().contains(energy),"Return did not distinguish Pokemon evolution stack from attached Energy/Tool");
    }
        for(PokemonFamily family:List.of(PokemonFamily.V,PokemonFamily.GX,PokemonFamily.EX,PokemonFamily.EX_LEGACY)){var c=config("swsh2_en_165");c.ownFamilies=Set.of(family);var m=GeneratedRuleBatch28Test.fixture(c);check(m.canPlayTrainer(A,card(m,A,"trainer").instanceId(),null)==(family!=PokemonFamily.V&&family!=PokemonFamily.GX),"Scoop Up Net confused modern ex/legacy EX with V/GX");}
    }
    static void exile(){for(String id:List.of("sm10_en_174","sm11-5_en_057"))for(int amount:List.of(1,2)){
        var m=GeneratedRuleBatch28Test.fixture(config(id));UUID first=m.benchPokemonView(A).getFirst().pokemonId();m.playBasicPokemonToBench(A,card(m,A,"attacker").instanceId());UUID second=m.benchPokemonView(A).getLast().pokemonId();m.playBasicPokemonToBench(A,card(m,A,"attacker").instanceId());UUID damaged=m.benchPokemonView(A).getLast().pokemonId();m.placeDamageCountersByEffect(A,A,damaged,1);var energy=card(m,A,"energy");m.attachEnergy(A,energy.instanceId(),first);int prizes=m.privateView(B).prizes().size();play(m);var choice=m.effectChoicePrompt(A);m.chooseEffectOption(A,choice.resolutionId(),choice.step(),amount-1);var q=m.effectPokemonPrompt(A);check(q.targets().stream().allMatch(p->!p.pokemonId().equals(damaged)&&!p.pokemonId().equals(m.activePokemonView(A).pokemonId())),"Exile offered damaged or Active Pokemon");pick(m,first);if(amount==2)pick(m,second);settle(m);check(m.benchPokemonView(A).size()==3-amount&&m.benchPokemonView(A).stream().anyMatch(p->p.pokemonId().equals(damaged))&&m.privateView(A).discard().contains(energy)&&m.privateView(B).prizes().size()==prizes,"Exile failed whole stack disposal or incorrectly awarded prizes");
    }}
    static void switchHealing(){for(String id:List.of("sm7-5_en_062","swsh10_en_154","xy9-5_en_066"))for(boolean damage:List.of(false,true)){
        var m=GeneratedRuleBatch28Test.fixture(config(id));UUID old=m.activePokemonView(A).pokemonId(),next=m.benchPokemonView(A).getFirst().pokemonId();if(damage)m.placeDamageCountersByEffect(A,A,old,5);m.placeDamageCountersByEffect(A,A,next,8);play(m);pick(m,old);pick(m,next);settle(m);check(m.activePokemonView(A).pokemonId().equals(next)&&m.activePokemonView(A).damage()==80&&m.benchPokemonView(A).stream().filter(p->p.pokemonId().equals(old)).findFirst().orElseThrow().damage()==(damage?20:0),"Switch heal affected incoming Active or failed undamaged switch");
    }
        var c=config("sm7-5_en_062");c.ownTypes=Set.of(EnergyType.GRASS);var wrong=GeneratedRuleBatch28Test.fixture(c);check(!wrong.canPlayTrainer(A,card(wrong,A,"trainer").instanceId(),null),"Switch Raft accepted non-Water Active");var evolved=GeneratedRuleBatch28Test.fixture(config("swsh10_en_154"));evolved.evolve(A,evolved.activePokemonView(A).pokemonId(),card(evolved,A,"evolved").instanceId());check(!evolved.canPlayTrainer(A,card(evolved,A,"trainer").instanceId(),null),"Switch Cart accepted evolved Active");
    }
}
